// Transport-agnostic server core shared by the vite and craco adapters: page-report
// store, replay persistence (+digest), health assembly, and client-source rendering.
import fs from "node:fs";
import path from "node:path";
import { buildReplayDigest } from "./digest.js";
export function createPageReports() {
    const reports = new Map();
    return {
        // Slots are kept, not deleted, so a late out-of-order message can't resurrect
        // pre-reload errors; the 45s TTL sweeps (heartbeat is 15s).
        record(data) {
            try {
                const parsed = (data ?? {});
                const page = typeof parsed.page === "string" ? parsed.page.slice(0, 100) : "unknown";
                // Whitelist + byte-cap every field: the channel is same-realm with generated app
                // code, so a single giant message must not become retained server memory.
                const errors = (Array.isArray(parsed.errors) ? parsed.errors : []).slice(0, 20).map((e) => {
                    const r = e && typeof e === "object" ? e : {};
                    return {
                        kind: String(r.kind ?? "").slice(0, 40),
                        message: String(r.message ?? "").slice(0, 2000),
                        file: r.file == null ? null : String(r.file).slice(0, 500),
                        count: Number(r.count) || 1,
                        replay: r.replay == null ? null : String(r.replay).slice(0, 300),
                    };
                });
                const splash = parsed.splash === true;
                const seq = Number(parsed.seq) || 0;
                const now = Date.now();
                for (const [k, r] of reports)
                    if (now - r.at > 45_000)
                        reports.delete(k);
                const prev = reports.get(page);
                if (!prev && reports.size >= 100)
                    return; // bound memory even on a trusted channel
                if (!prev || !seq || !prev.seq || seq >= prev.seq) {
                    reports.set(page, {
                        seq,
                        url: String(parsed.url || "").slice(0, 500),
                        errors,
                        splash,
                        at: now,
                    });
                }
            }
            catch {
                /* malformed report — ignore */
            }
        },
        // Sweeps expired slots and returns the pages the probe should surface.
        activePages() {
            const now = Date.now();
            const pages = [];
            for (const [page, r] of reports) {
                if (now - r.at > 45_000)
                    reports.delete(page);
                else if (r.errors.length > 0 || r.splash)
                    pages.push({ url: r.url, splash: r.splash, errors: r.errors, reported_ms_ago: now - r.at });
            }
            return pages;
        },
    };
}
// Dumps land in the workspace-level .emergent/recordings so the agent (and the
// backup) can reach them. Capped per kind, oldest pruned, digest sidecar per dump.
export function recordingsDir(root) {
    const parentEmergent = path.resolve(root, "..", ".emergent");
    const dir = fs.existsSync(parentEmergent)
        ? path.join(parentEmergent, "recordings")
        : path.resolve(root, ".emergent", "recordings");
    fs.mkdirSync(dir, { recursive: true });
    return dir;
}
export function saveReplay(root, req) {
    const kind = req.kind === "user-report" ? "user-report" : "crash";
    const dir = recordingsDir(root);
    const file = path.join(dir, `${kind}-${Date.now()}.json`);
    const body = JSON.stringify({
        kind,
        note: String(req.note ?? "").slice(0, 2000),
        url: String(req.url ?? "").slice(0, 500),
        viewport: req.viewport ?? null,
        error: req.error ?? null,
        recorder: typeof req.recorder === "string" ? req.recorder.slice(0, 20) : null,
        captured_at: new Date().toISOString(),
        events: Array.isArray(req.events) ? req.events : [],
    }, null, 0);
    if (body.length > 8_000_000)
        throw new Error("replay too large");
    fs.writeFileSync(file, body);
    // Sidecar digest: agents read this ~1KB timeline first, raw JSON only for detail.
    try {
        fs.writeFileSync(file.replace(/\.json$/, ".md"), buildReplayDigest({
            note: String(req.note ?? "").slice(0, 2000),
            url: String(req.url ?? "").slice(0, 500),
            error: req.error && typeof req.error === "object" ? req.error : null,
            recorder: typeof req.recorder === "string" ? req.recorder : undefined,
            events: Array.isArray(req.events) ? req.events : [],
        }));
    }
    catch {
        /* digest is best-effort; never fail the save */
    }
    const siblings = fs
        .readdirSync(dir)
        .filter((f) => f.startsWith(kind + "-") && f.endsWith(".json"))
        .sort();
    for (const old of siblings.slice(0, Math.max(0, siblings.length - 3))) {
        fs.rmSync(path.join(dir, old), { force: true });
        fs.rmSync(path.join(dir, old.replace(/\.json$/, ".md")), { force: true });
    }
    return file;
}
export function listReplays(root) {
    try {
        const parentEmergent = path.resolve(root, "..", ".emergent", "recordings");
        const dir = fs.existsSync(parentEmergent) ? parentEmergent : path.resolve(root, ".emergent", "recordings");
        return fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort().slice(-6) : [];
    }
    catch {
        return [];
    }
}
// Browser-free splash heuristic: the stock Home file still carries the marker.
export function splashInSource(root) {
    for (const home of ["src/pages/Home.tsx", "src/pages/Home.jsx", "src/pages/Home.js"]) {
        try {
            return fs.readFileSync(path.resolve(root, home), "utf8").includes("data-emergent-splash");
        }
        catch {
            /* try the next template flavor */
        }
    }
    return false;
}
export function healthPayload(root, pageReports, buildErrors) {
    const pages = pageReports.activePages();
    const buildError = buildErrors.length ? buildErrors[buildErrors.length - 1] : null;
    const healthy = !buildError && pages.every((p) => p.errors.length === 0);
    return {
        status: healthy ? 200 : 503,
        body: JSON.stringify({
            healthy,
            build_error: buildError,
            build_errors: buildErrors,
            splash_visible: pages.some((p) => p.splash),
            replays: listReplays(root),
            splash_in_source: splashInSource(root),
            pages,
        }),
    };
}
// Inlined (not a src= fetch) so it runs even when every module request fails.
// JSON-encode injected config (escaping "<" so "</script" can't terminate the tag).
export function renderClientSource(assetDir, cfg) {
    const inject = (v) => JSON.stringify(v).replace(/</g, "\\u003c");
    return fs
        .readFileSync(path.join(assetDir, "client.js"), "utf8")
        .replace('"__EMERGENT_BASE__"', () => inject(cfg.base))
        .replace('"__EMERGENT_HMR__" === "true"', () => String(cfg.hmrEnabled))
        .replace('"__EMERGENT_ROOT__"', () => inject(cfg.root))
        .replace('"__EMERGENT_RRWEB_MODE__"', () => inject(cfg.rrwebMode))
        .replace('"__EMERGENT_FAB__"', () => inject(cfg.fabMode))
        .replace('"__EMERGENT_NETWORK__"', () => inject(cfg.networkMode))
        .replace('"__EMERGENT_TRANSPORT__"', () => inject(cfg.transport))
        .replace('"__EMERGENT_TOKEN__"', () => inject(cfg.token));
}
export function rrwebAsset(assetDir) {
    return fs.readFileSync(path.join(assetDir, "rrweb.min.js"));
}
// EMERGENT_OVERLAY_RRWEB modes: "edge" (or legacy "true"), "buffer", or off.
export function resolveRrwebMode() {
    const raw = process.env.EMERGENT_OVERLAY_RRWEB || "";
    return raw === "true" ? "edge" : raw;
}
// The bug FAB ships dark by default; EMERGENT_OVERLAY_FAB=on is the product knob.
export function resolveFabMode() {
    return process.env.EMERGENT_OVERLAY_FAB === "on" ? "on" : "off";
}
// Network capture is opt-in: only EMERGENT_OVERLAY_NETWORK=on installs the fetch/XHR hook, so an
// absent knob (a template that does not plumb it yet, an image built before it did) stays off.
// Like the other knobs it reaches the dev server through supervisord's environment= line.
export function resolveNetworkMode() {
    return process.env.EMERGENT_OVERLAY_NETWORK === "on" ? "on" : "off";
}
